-- ============================================
-- LUMA — Thème 2 : scénario MOYEN 1/3 x4 — Premier rendez-vous dans un café
-- ============================================


update scenarios set content = '{"characters": {"alex": "Alex", "waiter": "le serveur"}, "start_node": "n1", "nodes": {"n1": {"speaker": "alex", "text": "Hi! Sorry, am I late? I couldn''t find parking.", "text_fr": "Salut ! Désolé, je suis en retard ? J''ai eu du mal à trouver une place.", "choices": [{"text": "Not at all, I just got here too.", "text_fr": "Pas du tout, je viens d''arriver aussi.", "next": "n2"}, {"text": "A little, but no worries, I was reading anyway.", "text_fr": "Un peu, mais t''inquiète, je lisais de toute façon.", "next": "n2b"}]}, "n2": {"speaker": "alex", "text": "Great! You look even better than your photos, by the way.", "text_fr": "Super ! Tu es encore mieux que sur tes photos, au fait.", "choices": [{"text": "Thank you, that''s sweet of you to say.", "text_fr": "Merci, c''est gentil de dire ça.", "next": "n3"}, {"text": "Ha, thanks — you too, honestly.", "text_fr": "Ha, merci — toi aussi, honnêtement.", "next": "n3"}]}, "n2b": {"speaker": "alex", "text": "Oh good, what are you reading?", "text_fr": "Oh super, tu lis quoi ?", "choices": [{"text": "Just a mystery novel, nothing too serious.", "text_fr": "Juste un roman policier, rien de trop sérieux.", "next": "n3"}, {"text": "Actually a book on hiking trails, for research.", "text_fr": "En fait un livre sur les sentiers de randonnée, pour me renseigner.", "next": "n3"}]}, "n3": {"speaker": "waiter", "text": "Hi there, what can I get you both to drink?", "text_fr": "Bonjour, je vous sers quoi à boire tous les deux ?", "choices": [{"text": "I''ll have a cappuccino, please.", "text_fr": "Je vais prendre un cappuccino, s''il vous plaît.", "next": "n4"}, {"text": "Could I get an iced tea?", "text_fr": "Je pourrais avoir un thé glacé ?", "next": "n4"}]}, "n4": {"speaker": "alex", "text": "So, tell me something about yourself that''s not on your profile.", "text_fr": "Alors, dis-moi quelque chose sur toi qui n''est pas sur ton profil.", "choices": [{"text": "I actually used to play in a band in college.", "text_fr": "En fait je jouais dans un groupe à la fac.", "next": "n5"}, {"text": "I''m secretly terrified of birds, don''t judge me.", "text_fr": "J''ai secrètement une peur des oiseaux, ne me juge pas.", "next": "n5b"}]}, "n5": {"speaker": "alex", "text": "No way, what did you play? That''s so cool!", "text_fr": "Sans blague, tu jouais de quoi ? C''est trop cool !", "choices": [{"text": "Guitar, mostly indie rock covers.", "text_fr": "De la guitare, surtout des reprises indie rock.", "next": "n6"}, {"text": "Drums actually, it was a lot of fun.", "text_fr": "De la batterie en fait, c''était super fun.", "next": "n6"}]}, "n5b": {"speaker": "alex", "text": "(Laughs) Birds? Really? That''s such a specific fear!", "text_fr": "(Rit) Les oiseaux ? Vraiment ? C''est une peur très spécifique !", "choices": [{"text": "I know, it''s irrational, but pigeons freak me out.", "text_fr": "Je sais, c''est irrationnel, mais les pigeons me terrifient.", "next": "n6"}]}, "n6": {"speaker": "alex", "text": "That''s a great story. Okay, my turn — I once got lost hiking for six hours.", "text_fr": "C''est une super histoire. Bon, à mon tour — je me suis déjà perdu en randonnée pendant six heures.", "choices": [{"text": "Oh no, what happened?", "text_fr": "Oh non, qu''est-ce qui s''est passé ?", "next": "n7"}, {"text": "Six hours?! Were you scared?", "text_fr": "Six heures ?! T''avais peur ?", "next": "n7b"}]}, "n7": {"speaker": "alex", "text": "I followed the wrong trail marker and ended up on the other side of the mountain.", "text_fr": "J''ai suivi le mauvais marquage et j''ai fini de l''autre côté de la montagne.", "choices": [{"text": "That sounds terrifying but also kind of an adventure.", "text_fr": "Ça a l''air terrifiant mais aussi un peu une aventure.", "next": "n8"}]}, "n7b": {"speaker": "alex", "text": "Honestly, a little, but I focused on staying calm and retracing my steps.", "text_fr": "Honnêtement, un peu, mais je me suis concentré sur le fait de rester calme et de retracer mes pas.", "choices": [{"text": "That''s impressive, I''d have panicked completely.", "text_fr": "C''est impressionnant, moi j''aurais complètement paniqué.", "next": "n8"}]}, "n8": {"speaker": "alex", "text": "It really was! Anyway — this conversation is flowing so easily.", "text_fr": "Ça l''était vraiment ! Enfin bref — cette conversation coule tellement facilement.", "choices": [{"text": "I was just thinking the same thing.", "text_fr": "Je pensais exactement la même chose.", "next": "n9"}, {"text": "It''s rare to click with someone this fast.", "text_fr": "C''est rare de bien s''entendre avec quelqu''un aussi vite.", "next": "n9"}]}, "n9": {"speaker": "waiter", "text": "Can I get you two anything else, or the check?", "text_fr": "Je peux vous apporter autre chose, ou l''addition ?", "choices": [{"text": "Actually, could we get some pastries too? I''m not ready to leave yet.", "text_fr": "En fait, on pourrait avoir des pâtisseries aussi ? Je ne suis pas prêt à partir.", "next": "n10"}, {"text": "Just the check, thank you.", "text_fr": "Juste l''addition, merci.", "next": "n10b"}]}, "n10": {"speaker": "alex", "text": "I love that idea, let''s stay a bit longer.", "text_fr": "J''adore cette idée, restons encore un peu.", "choices": [{"text": "Perfect, I''m really enjoying this.", "text_fr": "Parfait, je passe vraiment un bon moment.", "next": "n11"}]}, "n10b": {"speaker": "alex", "text": "Oh, already? Well, I guess time flies when you''re having fun.", "text_fr": "Oh, déjà ? Bon, je suppose que le temps passe vite quand on s''amuse.", "choices": [{"text": "It really does — this was really nice.", "text_fr": "C''est vraiment vrai — c''était vraiment sympa.", "next": "n11"}]}, "n11": {"speaker": "alex", "text": "This has been such a great time. I''d love to see you again.", "text_fr": "C''était un si bon moment. J''aimerais vraiment te revoir.", "choices": [{"text": "I''d really like that too.", "text_fr": "J''aimerais vraiment ça aussi.", "next": "end_great"}, {"text": "Me too — same time next week?", "text_fr": "Moi aussi — même heure la semaine prochaine ?", "next": "end_planned"}]}, "end_great": {"speaker": "alex", "text": "Great, I''ll text you! This was honestly one of my best first dates.", "text_fr": "Super, je t''écris ! Honnêtement l''un de mes meilleurs premiers rendez-vous.", "end": true, "ending_label": "Premier rendez-vous réussi, une vraie connexion ☕💕"}, "end_planned": {"speaker": "alex", "text": "I love the initiative — it''s a date, literally!", "text_fr": "J''adore l''initiative — c''est un rendez-vous, littéralement !", "end": true, "ending_label": "Deuxième rendez-vous déjà planifié 📅💕"}}}'::jsonb, is_playable = true
where title = 'Premier rendez-vous dans un café'
  and theme_id = (select id from scenario_themes where position = 2 and language_id = (select id from languages where code = 'en'));
